-- Isolated PostgreSQL only; never run against the project database.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$SELECT nullif(current_setting('request.uid',true),'')::uuid$$;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz,deleted_at timestamptz,banned_until timestamptz);
CREATE TABLE public.account_access_revocations(user_id uuid);
CREATE TABLE public.members_data(id integer PRIMARY KEY,member_type text);
CREATE TABLE public.member_allowed_emails(member_id integer,email text);
CREATE TABLE public.member_profiles(user_id uuid,member_id integer,UNIQUE(user_id,member_id));
ALTER TABLE public.member_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users can link own verified member" ON public.member_profiles FOR INSERT TO authenticated WITH CHECK(true);
CREATE TABLE public.user_roles(user_id uuid,role text,UNIQUE(user_id,role));
CREATE FUNCTION public.has_role(u uuid,r text) RETURNS boolean LANGUAGE sql AS $$SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=u AND role=r)$$;
CREATE TABLE public.membership_requests(id uuid DEFAULT gen_random_uuid(),email text,status text,created_at timestamptz DEFAULT now());
CREATE TABLE public.external_organizations(id uuid DEFAULT gen_random_uuid() PRIMARY KEY,name text,type text,contact_email text,contact_name text,approved boolean DEFAULT false);
CREATE TABLE public.external_org_users(org_id uuid,user_id uuid);
CREATE TABLE public.member_benefits(id uuid DEFAULT gen_random_uuid(),supplier_org_id uuid);
ALTER TABLE public.member_benefits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Suppliers can insert own benefits" ON public.member_benefits FOR INSERT TO authenticated WITH CHECK(true);
CREATE POLICY "Suppliers can update own benefits" ON public.member_benefits FOR UPDATE TO authenticated USING(true);
CREATE POLICY "Suppliers can delete own benefits" ON public.member_benefits FOR DELETE TO authenticated USING(true);
